%[text] # Profiling simulation with Reducer Basic model
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] Run simulation using the Solver Profiler's `solverprofiler.profileModel` function. See the documentation about the function for details.
%[text] - [https://www.mathworks.com/help/simulink/slref/solverprofiler.profilemodel.html](https://www.mathworks.com/help/simulink/slref/solverprofiler.profilemodel.html) \
%[text] ## Set up
model_name = "Reducer_TestModel";
target_folder = fullfile(currentProject().RootFolder, "Components", "Reducer", "Model-Basic", "SimulationCases");
data_fullpath = fullfile(target_folder, "profiling_data.mat");
%[text] ## Run simulation normally
assert(isfolder(target_folder))
load_system(model_name);
close_system(model_name + "/Measurement/Scope")
set_param(model_name, StopTime="100");
evalin("base", "Reducer_Basic_params")
%[text] Input signals. These are used in PS Lookup Table (1D) blocks in the model.
Reducer_setInput_AxleSide_1 %[output:3f3de1c9]
Reducer_setInput_MotorSide_1 %[output:212bbfb8]
%[text] Run simulation normally and plot results.
simOut = sim(model_name);
tt = SignalTool2.getTimetableFromLoggedSignal(simOut.logsout);
varnames = string(tt.Properties.VariableNames);
for idx = 1 : numel(varnames) %[output:group:7c2b9be0]
  SignalTool2.plotTimedData(TimedData=tt, SignalName=varnames(idx)); %[output:8579231f] %[output:5ca3233c] %[output:3bb9c51c] %[output:286fff6d]
end  % for %[output:group:7c2b9be0]
%%
%[text] ## Step size
fig = figure;
fig.Position(3:4) = [800, 200];  % width, height
SignalTool2.plotDifference(simOut.tout, NewFigure=false, ParentAxes=axes(fig), ...
  Title="Step size", XLabel="Time", XUnitText="s", YUnitText="s")
step_size_data = diff(simOut.tout);
disp("Maximum step size: " + max(step_size_data)) %[output:424dc2b7]
fprintf("Minimum step size: %e", min(step_size_data)) %[output:9a78d849]
%%
%[text] ## Profiling simulation
%[text] Run profiling simulation using the Solver Profiler.
open_system(model_name) %[output:9987b518]
open_system(model_name + "/Measurement/Scope")
result = solverprofiler.profileModel( ... %[output:group:97b34df3] %[output:9987b518]
  model_name, ... %[output:9987b518]
  DataFullFile = data_fullpath, ... %[output:9987b518]
  OpenSP = "off", ... Set "on" to open the Solver Profiler after completing profiling. %[output:9987b518]
  TimeOut = 10, ... in seconds. Stop the profiling simulation if the simulation does not make progress. %[output:9987b518]
  StartTime = 0, ... Start time in seconds for profiling. Simulation starts from the model's StartTime which is usually 0. %[output:9987b518]
  StopTime = 100, ... Stop time in seconds for simulation and profiling. The model's StopTime is not affected by this option. %[output:9987b518]
  BufferSize = 50000, ... Maximum number of events to log. %[output:9987b518]
  SaveStates = "on", ... %[output:9987b518]
  SaveSimscapeStates = "on", ... %[output:9987b518]
  SaveJacobian = "on", ... %[output:9987b518]
  SaveZCSignals = "on" ); %[output:group:97b34df3] %[output:9987b518]
%[text] View the high-level summary of profiling result. See the documentation for details.
%[text] - `tStart` - Start time in seconds for profiling. Can be different from simulation start time.
%[text] - `tStop` - Stop time in seconds for profiling. Can be different from simulation stop time.
%[text] - `absTol` - Absolute tolerance for the solver.
%[text] - `relTol` - Relative tolerance for the solver.
%[text] - `hMax` - Maximum step size.
%[text] - `hAverage` - Average size of steps taken by the solver.
%[text] - `steps` - Total number of time steps.
%[text] - `profileTime` - Elapsed time in seconds.
%[text] - `zcNumber` - Number of zero crossings detected.
%[text] - `resetNumber` - Number of solver resets that occurred.
%[text] - `jacobianNumber` - Number of times the solver updated the Jacobian matrix.
%[text] - `exceptionNumber` - Total number of solver exceptions that occurred. \
disp(result.summary) %[output:7294de90]
%[text] Open the Solver Profiler with the saved session data.
%solverprofiler.exploreResult(char(data_fullpath))
